(()=>{const key='upk-riverton-golden-drops-v1',image='/assets/images/kids/golden-drop.webp';let found=[];try{const x=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(x))found=[...new Set(x.filter(n=>Number.isInteger(n)&&n>=1&&n<=10))]}catch(e){}let saved=true;const d=document.createElement('dialog');d.className='rv-panel';d.setAttribute('aria-labelledby','rv-title');d.innerHTML='<h2 id="rv-title">My Riverton Treasures</h2><p class="rv-message" aria-live="polite"></p><div class="rv-slots"></div><p class="rv-status"></p><div class="rv-reward" hidden><h3>Riverton Treasure Hunter!</h3><p>You found all ten Golden Drops!</p><button type="button" class="rv-action rv-print">Print your secret coloring badge</button></div><p><button type="button" class="rv-action rv-close">Keep exploring</button></p>';document.body.append(d);function render(){document.querySelectorAll('.rv-count').forEach(e=>e.textContent=found.length+' / 10');document.querySelectorAll('.rv-drop').forEach(e=>{const yes=found.includes(Number(e.dataset.drop));e.dataset.found=yes;e.setAttribute('aria-label',yes?'Golden Drop already collected':'Collect Golden Drop')});d.querySelector('.rv-slots').replaceChildren(...Array.from({length:10},(_,i)=>{const s=document.createElement('span');s.className='rv-slot';s.textContent=i<found.length?'':'?';if(i<found.length){const im=document.createElement('img');im.src=image;im.alt='Collected Golden Drop';s.append(im)}return s}));d.querySelector('.rv-status').textContent=found.length+' of 10 collected. '+(saved?'Progress is saved in this browser.':'Browser storage unavailable; progress may not persist.');d.querySelector('.rv-reward').hidden=found.length!==10}function show(msg){render();d.querySelector('.rv-message').textContent=msg;if(!d.open)d.showModal()}document.querySelectorAll('.rv-drop').forEach(e=>e.addEventListener('click',()=>{const n=Number(e.dataset.drop);if(found.includes(n)){show('You already found this Golden Drop!');return}found.push(n);try{localStorage.setItem(key,JSON.stringify(found))}catch(e){saved=false}show(found.length===10?'Amazing! You found every Golden Drop!':'You found a Golden Drop!')}));document.querySelectorAll('.rv-open').forEach(e=>e.addEventListener('click',()=>show('Keep your eyes open as you explore Riverton!')));d.querySelector('.rv-close').onclick=()=>d.close();d.querySelector('.rv-print').onclick=()=>{const w=window.open('','_blank');if(!w){alert('Allow pop-ups to print your reward.');return}w.document.write("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Under Pressure Kids | Riverton Treasure Hunter</title><style>@page{size:letter portrait;margin:0.25in}*{box-sizing:border-box}body{margin:0;text-align:center;background:white;font-family:sans-serif}img{display:block;width:100%;max-width:8in;height:auto;margin:0 auto}button{margin:12px;padding:10px 24px;font-size:18px}@media print{button{display:none!important}html,body{margin:0;padding:0}img{width:8in;height:10.5in;object-fit:contain;break-inside:avoid;print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><img alt=\"Riverton Treasure Hunter certificate: I found all ten Golden Drops!\" src=\"data:image/png;base64,\"><button onclick=\"window.print()\">Print certificate</button></body></html>");w.document.close()};render()})();